from typing import List, Dict, Any
from google.cloud import documentai_v1 as documentai
from google.api_core.client_options import ClientOptions
import os

def extract_receipt_data(project_id: str, location: str, processor_id: str, file_path: str) -> Dict[str, Any]:
    # Set up client options to specify the region
    client_options = ClientOptions(api_endpoint=f"{location}-documentai.googleapis.com")
    client = documentai.DocumentProcessorServiceClient(client_options=client_options)

    # The full resource name of the processor
    name = client.processor_path(project_id, location, processor_id)

    # Read the file into memory
    with open(file_path, "rb") as image:
        image_content = image.read()

    # Configure the process request
    raw_document = documentai.RawDocument(content=image_content, mime_type="application/pdf") # or image/jpeg, image/png

    # Use the process_document method to send the request and get the response
    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    result = client.process_document(request=request)
    document = result.document

    # Initialize extracted data dictionary
    extracted_data = {
        "merchant": None,
        "tax": None,
        "total": None,
        "items": []
    }

    # Helper function to get text from a text_anchor
    def get_text(text_anchor: documentai.Document.TextAnchor) -> str:
        if not text_anchor.text_segments:
            return ""
        # Assuming one segment for simplicity; for multi-segment, you'd combine
        start_index = text_anchor.text_segments[0].start_index
        end_index = text_anchor.text_segments[0].end_index
        return document.text[start_index:end_index]

    # Extract entities
    for entity in document.entities:
        if entity.type_ == "merchant_name":
            extracted_data["merchant"] = get_text(entity.text_anchor)
        elif entity.type_ == "total_amount":
            # Extracting the numerical value directly if available, otherwise text
            if entity.mention_text:
                extracted_data["total"] = float(entity.mention_text)
            elif entity.text_anchor:
                try:
                    extracted_data["total"] = float(get_text(entity.text_anchor))
                except ValueError:
                    extracted_data["total"] = get_text(entity.text_anchor)
        elif entity.type_ == "tax_amount":
            if entity.mention_text:
                extracted_data["tax"] = float(entity.mention_text)
            elif entity.text_anchor:
                try:
                    extracted_data["tax"] = float(get_text(entity.text_anchor))
                except ValueError:
                    extracted_data["tax"] = get_text(entity.text_anchor)
        elif entity.type_ == "line_item":
            item_data = {}
            for prop in entity.properties:
                if prop.type_ == "line_item_description":
                    item_data["description"] = get_text(prop.text_anchor)
                elif prop.type_ == "line_item_amount":
                    if prop.mention_text:
                        item_data["amount"] = float(prop.mention_text)
                    elif prop.text_anchor:
                        try:
                            item_data["amount"] = float(get_text(prop.text_anchor))
                        except ValueError:
                            item_data["amount"] = get_text(prop.text_anchor)
                # You might add other item properties like "quantity", "price" etc.
            if item_data:
                extracted_data["items"].append(item_data)

    return extracted_data
